def build_loc_columns(d:Dict[str,str]):
    """Construct column header list for locations"""
    my_list:List[str] = list(d.keys())
    my_list.sort()
    return my_list


def parse_lon_output(s:str):
    """Convert value at location string from wgrib2 into ["LatLon_$lat_$lon", "val"]:

        'lon=262.734337,lat=27.660547,val=0' → ['LatLon_27.660547_262.734337', '0']

    FMI https://www.cpc.ncep.noaa.gov/products/wesley/wgrib2/lon.html
    """
    m = re.search(r'^lon=([\d.]+),lat=([\d.]+),val=(-?[\d.]+(?:e[+-]\d+)?)$', s)
    # Throw error if we don't match?!  (unexpected format)
    if (not m):
        logger.error(f'Don\'t know how to parse [value] "{s}"')
    return [f'LatLon_{m[2]}_{m[1]}', m[3]]


